import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import Swal from "sweetalert2";

export default function ParentFeePage() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [summary, setSummary] = useState(null);
  const [amount, setAmount] = useState("");
  const [structure, setStructure] = useState(null);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/fees")
      .then((res) => {
        if (res.data.success) setStructure(res.data.data);
      })
      .catch(() => toast.error("Failed to load overall fee structure"));
  }, []);

  // const getVisibleFeeKeys = (cls) => {
  //   if (cls <= 5) return ["tuition", "development", "transport"];
  //   if (cls >= 6 && cls <= 9)
  //     return ["tuition", "development", "computer", "transport", "sports"];
  //   return ["tuition", "development", "computer", "sports", "artMusic"];
  // };
  // const getVisibleFeeKeys = (cls) => {
  //   if (cls <= 5)
  //   return ["tuition", "development", "transport"]; // primary

  //   if (cls >= 6 && cls <= 9)
  //   return ["tuition", "development", "computer", "transport", "sports"]; // middle

  //   if (cls >= 10 && cls <= 12)
  //   return ["tuition", "development", "computer", "sports", "artMusic"]; // senior (no transport)

  //   return ["tuition", "development"]; // fallback
  // };
  // Handles string or number formats safely
  const getVisibleFeeKeys = (cls) => {
   // Ensure class is treated as a number
   const classNum = parseInt(cls, 10);

   if (isNaN(classNum)) return ["tuition", "development"]; // fallback if parsing fails

   if (classNum <= 5)
    return ["tuition", "development", "transport"]; // primary

   if (classNum >= 6 && classNum <= 9)
    return ["tuition", "development", "computer", "transport", "sports"]; // middle

   if (classNum >= 10 && classNum <= 12)
    return ["tuition", "development", "computer", "sports", "artMusic"]; // senior (no transport)

   return ["tuition", "development"];
  };


  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Please enter admission number");
    try {
      const res = await axios.get(
        `http://localhost:5000/api/fees/student/${admissionNo}`
      );
      if (res.data.success && res.data.data) {
        setSummary(res.data.data);
        toast.success("Fee record loaded!");
      } else {
        setSummary(null);
        toast.error("No record found!");
      }
    } catch {
      toast.error("Failed to load fee structure");
    }
  };

  const payNow = async () => {
    const amt = Number(amount);
    if (!amt || amt <= 0) return toast.error("Enter valid amount");

    const ok = await Swal.fire({
      title: `Pay ₹${amt}?`,
      text: "Proceed to simulated payment?",
      showCancelButton: true,
    });
    if (!ok.isConfirmed) return;

    try {
      const feeItems = summary.fee.items;
      // const mainFeeKeys = getVisibleFeeKeys(Number(summary.student.className));
      // const mainFeeKeys = getVisibleFeeKeys(summary.student.className);
      const mainFeeKeys = getVisibleFeeKeys(summary.student.classApplied || summary.student.className);

      console.log("Class received:", summary.student.className);


      const breakdown = {};
      let remainingAmount = amt;

      mainFeeKeys.forEach((k) => {
        if (!feeItems[k]) return;
        const rem = Math.max(
          0,
          feeItems[k].amount -
            (summary.payments?.reduce(
              (pSum, p) => pSum + (p.breakdown?.[k] || 0),
              0
            ) || 0)
        );
        if (remainingAmount >= rem) {
          breakdown[k] = rem;
          remainingAmount -= rem;
        } else {
          breakdown[k] = remainingAmount;
          remainingAmount = 0;
        }
      });

      const res = await axios.post("http://localhost:5000/api/fees/pay", {
        admissionNo,
        amount: amt,
        method: "simulated",
        breakdown,
      });

      if (res.data.success) {
        await Swal.fire({
          icon: "success",
          title: "Payment Successful!",
          html: `<p><b>Amount Paid:</b> ₹${amt}</p>`,
          confirmButtonText: "OK",
        });
        setSummary(null);
        setAdmissionNo("");
        setAmount("");
      } else {
        toast.error(res.data.error || "Payment failed");
      }
    } catch {
      toast.error("Payment failed");
    }
  };

  return (
    <div className="fee-page">
      <Toaster />

      {structure && (
        <div className="overall-structure">
          <h2>School Fee Structure ({structure.academicYear})</h2>
          <div dangerouslySetInnerHTML={{ __html: structure.notes }} />
          <table className="fee-table">
            <thead>
              <tr>
                <th>Particulars</th>
                <th>Amount (₹)</th>
              </tr>
            </thead>
            <tbody>
              {structure.items.map((item) => (
                <tr key={item.key}>
                  <td>{item.title}</td>
                  <td>{item.amount}</td>
                </tr>
              ))}
              <tr className="fee-total">
                <td><b>Total</b></td>
                <td>
                  <b>₹{structure.items.reduce((s, i) => s + i.amount, 0)}</b>
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      )}

      {/* 🔹 Directly show admission input (no Pay Fee button inside page) */}
      <div className="search-box" style={{ marginTop: "30px" }}>
        <h3>Enter Student Details to Continue</h3>
        <input
          type="text"
          style={{ width: "260px", height: "30px" }}
          value={admissionNo}
          onChange={(e) => setAdmissionNo(e.target.value)}
          placeholder="Enter Admission Number (e.g. KV-000000)"
        />
        <button className="search-btn" onClick={fetchFee}>
          Search
        </button>
      </div>

      {summary && (
        <div className="fee-card">
          <h3>
            Fee Structure for {summary.student.studentName} (
            {summary.student.admissionNo}) — Class {summary.student.className}
          </h3>

          {(() => {
            // const cls = Number(summary.student.className);
            const cls = summary.student.className;
            const mainFeeKeys = getVisibleFeeKeys(cls);
            return (
              <table className="fee-table">
                <thead>
                  <tr>
                    <th>Particulars</th>
                    <th>Amount (₹)</th>
                  </tr>
                </thead>
                <tbody>
                  {mainFeeKeys.map((key) => (
                    <tr key={key}>
                      <td>{summary.fee.items[key]?.title}</td>
                      <td>₹{summary.fee.items[key]?.amount}</td>
                    </tr>
                  ))}
                  <tr className="fee-total">
                    <td><b>Total</b></td>
                    <td>
                      <b>
                        ₹
                        {mainFeeKeys
                          .reduce(
                            (sum, k) =>
                              sum + (summary.fee.items[k]?.amount || 0),
                            0
                          )
                          .toLocaleString()}
                      </b>
                    </td>
                  </tr>
                </tbody>
              </table>
            );
          })()}

          <div className="pay-section">
            <input
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="Enter amount to pay"
            />
            <button onClick={payNow}>Pay Now</button>
          </div>
        </div>
      )}
    </div>
  );
}














